  var recv = {};
  var lsOK = (function () { try { localStorage.setItem(NS + '__t', '1'); localStorage.removeItem(NS + '__t'); return true; } catch (e) { return false; } })();

  function clone(v) { return v === undefined ? v : JSON.parse(JSON.stringify(v)); }
  function rawGet(k) { try { return lsOK ? localStorage.getItem(NS + k) : (mem[k] || null); } catch (e) { return mem[k] || null; } }
